package com.primehr.performancemanagement.domain;import com.primehr.rsp.domain.RspAuditedEntity;import jakarta.persistence.*;import java.time.*;import java.util.*;
@Entity @Table(name="spms_pmt_member",uniqueConstraints=@UniqueConstraint(name="uk_spms_pmt_member_period",columnNames={"agency_id","pmt_id","employee_no","effective_from"}))
public class PerformanceManagementTeamMember extends RspAuditedEntity{public enum Role{CHAIRPERSON,VICE_CHAIRPERSON,SECRETARIAT,MEMBER,TECHNICAL_SUPPORT}
 @Column(name="pmt_id",nullable=false,length=36)private String pmtId;@Column(name="employee_id",nullable=false)private Long employeeId;@Column(name="employee_no",nullable=false,length=100)private String employeeNo;@Column(name="employee_name_snapshot",nullable=false,length=300)private String employeeNameSnapshot;@Column(name="job_position_id_snapshot")private Long jobPositionIdSnapshot;@Column(name="plantilla_id_snapshot")private Long plantillaIdSnapshot;@Enumerated(EnumType.STRING)@Column(name="member_role",nullable=false,length=30)private Role role;@Column(nullable=false)private boolean voting;@Column(name="effective_from",nullable=false)private LocalDate effectiveFrom;@Column(name="effective_to")private LocalDate effectiveTo;@Column(name="designation_reference",length=500)private String designationReference;@Column(length=1000)private String remarks;
 protected PerformanceManagementTeamMember(){}public PerformanceManagementTeamMember(String agency,String pmt,Long employeeId,String employeeNo,String name,Long job,Long plantilla,Role role,boolean voting,LocalDate from,LocalDate to,String designation,String remarks){super(agency);pmtId=requiredText(pmt,"pmtId");this.employeeId=Objects.requireNonNull(employeeId,"employeeId");this.employeeNo=requiredText(employeeNo,"employeeNo");employeeNameSnapshot=requiredText(name,"employeeNameSnapshot");jobPositionIdSnapshot=job;plantillaIdSnapshot=plantilla;this.role=Objects.requireNonNull(role);if((role==Role.SECRETARIAT||role==Role.TECHNICAL_SUPPORT)&&voting)throw new IllegalArgumentException(role+" cannot be voting");if(role==Role.CHAIRPERSON&&!voting)throw new IllegalArgumentException("CHAIRPERSON must be voting");this.voting=voting;effectiveFrom=Objects.requireNonNull(from,"effectiveFrom");effectiveTo=to;if(to!=null&&to.isBefore(from))throw new IllegalArgumentException("Member effectiveTo cannot precede effectiveFrom");designationReference=optionalText(designation);this.remarks=optionalText(remarks);}
 public boolean effectiveOn(LocalDate day){return !day.isBefore(effectiveFrom)&&(effectiveTo==null||!day.isAfter(effectiveTo));}public String getPmtId(){return pmtId;}public Long getEmployeeId(){return employeeId;}public String getEmployeeNo(){return employeeNo;}public String getEmployeeNameSnapshot(){return employeeNameSnapshot;}public Long getJobPositionIdSnapshot(){return jobPositionIdSnapshot;}public Long getPlantillaIdSnapshot(){return plantillaIdSnapshot;}public Role getRole(){return role;}public boolean isVoting(){return voting;}public LocalDate getEffectiveFrom(){return effectiveFrom;}public LocalDate getEffectiveTo(){return effectiveTo;}public String getDesignationReference(){return designationReference;}public String getRemarks(){return remarks;}
}
